1	import { type NextRequest } from "next/server";
2	import { z } from "zod";
3	import { getUser } from "@/lib/auth";
4	import { createClient } from "@/lib/supabase/server";
5	import {
6	  getBooking,
7	  getSessionByBooking,
8	  getApprovedProvider,
9	} from "@/lib/db/queries";
10	import { formatCents } from "@/lib/format";
11	import { durationLabel } from "@/lib/time";
12	import { t } from "@/lib/i18n";
13	
14	/**
15	 * Downloadable plain-text receipt for a completed booking. Returns an
16	 * attachment; the booking must belong to the caller (RLS-enforced read).
17	 */
18	export async function GET(
19	  _req: NextRequest,
20	  ctx: { params: Promise<{ bookingId: string }> },
21	) {
22	  const user = await getUser();
23	  if (!user) {
24	    return new Response(t("receipt.notFound"), { status: 401 });
25	  }
26	  const { bookingId } = await ctx.params;
27	  if (!z.string().uuid().safeParse(bookingId).success) {
28	    return new Response(t("receipt.notFound"), { status: 404 });
29	  }
30	  const [booking, session] = await Promise.all([
31	    getBooking(bookingId),
32	    getSessionByBooking(bookingId),
33	  ]);
34	  if (!booking || booking.customer_id !== user.id || !session) {
35	    return new Response(t("receipt.notFound"), { status: 404 });
36	  }
37	
38	  const provider = await getApprovedProvider(booking.provider_id);
39	  const supabase = await createClient();
40	  const { data: payment } = await supabase
41	    .from("payments")
42	    .select("payment_ref, status")
43	    .eq("booking_id", bookingId)
44	    .maybeSingle();
45	
46	  const lines = [
47	    t("receipt.heading"),
48	    "",
49	    `${t("receipt.booking")}: ${booking.id}`,
50	    `${t("receipt.listener")}: ${provider?.display_name ?? "—"}`,
51	    `${t("receipt.date")}: ${session.ended_at ?? "—"}`,
52	    `${t("receipt.duration")}: ${durationLabel(session.elapsed_seconds)}`,
53	    `${t("receipt.block")}: ${t("receipt.minutes", { minutes: session.block_minutes })}`,
54	    session.overage_minutes > 0
55	      ? `${t("receipt.overage")}: ${t("receipt.minutes", { minutes: session.overage_minutes })}`
56	      : null,
57	    `${t("receipt.total")}: ${formatCents(session.total_price_cents)}`,
58	    `${t("receipt.payment")}: ${payment?.payment_ref ?? "—"} (${payment?.status ?? "—"})`,
59	    "",
60	    t("receipt.footer"),
61	    "",
62	  ]
63	    .filter((l) => l !== null)
64	    .join("\n");
65	
66	  return new Response(lines, {
67	    status: 200,
68	    headers: {
69	      "Content-Type": "text/plain; charset=utf-8",
70	      "Content-Disposition": `attachment; filename="heard-receipt-${booking.id.slice(0, 8)}.txt"`,
71	    },
72	  });
73	}
