157	/** Update the customer's display name. */
158	export async function updateProfileName(
159	  name: string,
160	): Promise<{ ok: boolean; error?: string }> {
161	  const profile = await requireRole("customer");
162	  const trimmed = name.trim();
163	  if (trimmed.length < 1 || trimmed.length > 120) {
164	    return { ok: false, error: "Enter your name." };
165	  }
166	  const supabase = await createClient();
167	  const { error } = await supabase
168	    .from("profiles")
169	    .update({ full_name: trimmed })
170	    .eq("id", profile.id);
171	  if (error) return { ok: false, error: "Could not save your name." };
172	  revalidatePath("/account/settings");
173	  return { ok: true };
174	}
